-- composition of rule kernels empty_result_pullup x grouping_sets (duckdb), template not_exists
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 FROM t4 AS a1 WHERE NULL::boolean EXCEPT (SELECT FALSE AS c0, FALSE AS c1, ARRAY['1'::text] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2))) AS ka WHERE NOT EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, BOOL_AND (FALSE) AS c1, [NULL]::text[] AS c2 FROM rc AS a1 GROUP BY ROLLUP (a1.c0) UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, []::text[] AS c2)) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, BOOL_AND (FALSE) AS c1, [NULL]::text[] AS c2 FROM rc AS a1 GROUP BY ROLLUP (a1.c0) UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, []::text[] AS c2)) AS kb) = 0 THEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 FROM t4 AS a1 WHERE NULL::boolean EXCEPT (SELECT FALSE AS c0, FALSE AS c1, ARRAY['1'::text] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2))) AS ka) ELSE 0 END
